import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.BAQ5ZYJQ.js";const c=JSON.parse('{"title":"Adopting a suite","description":"","frontmatter":{},"headers":[],"relativePath":"guide/runners/adopting.md","filePath":"guide/runners/adopting.md","lastUpdated":1794833911000}'),n={name:"guide/runners/adopting.md"};function h(r,s,p,l,d,o){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="adopting-a-suite" tabindex="-1">Adopting a suite <a class="header-anchor" href="#adopting-a-suite" aria-label="Permalink to &quot;Adopting a suite&quot;">​</a></h1><p>A pytest suite, a Catch2 suite and a cargo one, none of them modified, put under errand by three lines of <code>errand-project.py</code>. The project is <a href="https://github.com/hleclerc/errand/tree/main/examples/02-existing-suite" target="_blank" rel="noreferrer"><code>examples/02-existing-suite</code></a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/02-existing-suite</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>errand-project.py        three runners, and nothing else</span></span>
<span class="line"><span>tests/test_api.py        ordinary pytest, still runs under \`pytest\`</span></span>
<span class="line"><span>cpp/test_geometry.cpp    ordinary Catch2, still runs on its own</span></span>
<span class="line"><span>cpp/Makefile             whatever you already build with</span></span>
<span class="line"><span>rust/                    ordinary cargo</span></span></code></pre></div><p>It declares no environment, on purpose: declaring one would have running it build a micromamba environment on your machine. Environments are <a href="/errand/tutorials/environments">the first tutorial</a>.</p><h2 id="the-three-lines" tabindex="-1">The three lines <a class="header-anchor" href="#the-three-lines" aria-label="Permalink to &quot;The three lines&quot;">​</a></h2><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># errand-project.py</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> errand</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">errand.configure( </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;src&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ] )</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">errand.runners.replace( errand.Pytest( </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">dirs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tests&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ] ) )</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">errand.runners.replace( errand.Catch2( </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">dir</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;cpp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">build</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;make -C cpp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ) )</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">errand.runners.replace( errand.Cargo( </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">manifest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;rust/Cargo.toml&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ) )</span></span></code></pre></div><p>pytest, Catch2 and cargo are runners already, active with no configuration. These lines only say where to look and how to build. Not a line of the tests changes.</p><h2 id="running-it" tabindex="-1">Running it <a class="header-anchor" href="#running-it" aria-label="Permalink to &quot;Running it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;**::*&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                        # all three suites</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tests/test_api.py::*&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # the python ones</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cpp/test_geometry.cpp::area</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # one Catch2 case, by name</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;tests/**::*&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;not slow&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # pytest&#39;s own filter, after the target</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # the pytest command itself, recorded as one run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;**::*&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # what is there, and which runner took it</span></span></code></pre></div><p>The <code>::</code> is what sends a target to the suites&#39; runners; without it, <code>pytest</code> is just a command. To make a bare <code>errand run</code> mean all three, add to <code>errand-project.py</code>:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">errand.default_run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;**::*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]</span></span></code></pre></div><p>With environments declared, the same targets run in several of them at once: <code>errand run --grid=, --env local,old &#39;**::*&#39;</code>.</p><h2 id="numbers-from-a-catch2-benchmark" tabindex="-1">Numbers from a Catch2 benchmark <a class="header-anchor" href="#numbers-from-a-catch2-benchmark" aria-label="Permalink to &quot;Numbers from a Catch2 benchmark&quot;">​</a></h2><p><code>cpp/test_geometry.cpp</code> holds a Catch2 benchmark. It measured something, and the measurement went to the terminal and was lost. Under errand it lands in <code>result.yaml</code>, per machine and per date:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;cpp/test_geometry.cpp::area is cheap&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> errand-outputs/runs/cpp/test_geometry.cpp/area_is_cheap/latest/result.yaml</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # area_ns: …</span></span></code></pre></div><h2 id="letting-errand-write-the-lines" tabindex="-1">Letting errand write the lines <a class="header-anchor" href="#letting-errand-write-the-lines" aria-label="Permalink to &quot;Letting errand write the lines&quot;">​</a></h2><p>Move the file aside and have errand suggest one from the bare directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> errand-project.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> errand-project.bak</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # errand-project.py again, the runner lines in comments, and an errand-envs.py</span></span></code></pre></div><p>What it found is written <strong>in comments</strong>, with a <code>default_run</code> to start from: nothing is active until you uncomment it. The <code>errand.configure( src = … )</code> line is not in it: where your package lives is not something a directory can tell, so it is yours to add.</p><h2 id="building-and-finding-the-binary" tabindex="-1">Building, and finding the binary <a class="header-anchor" href="#building-and-finding-the-binary" aria-label="Permalink to &quot;Building, and finding the binary&quot;">​</a></h2><p>errand compiles nothing itself. It runs the command you already build with, once, and then expects the binaries where you say they land:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">errand.runners.replace( errand.Catch2( </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">dir</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;cpp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">build</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;make -C cpp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ) )</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">errand.runners.replace( errand.Catch2( </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">dir</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;cpp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">build</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;cmake --build build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">binary</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;build/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{stem}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ) )</span></span></code></pre></div><p><code>build</code> runs once, during the preparation, in the place the binaries run. <code>binary</code> defaults to the source without its extension, which is where the Makefile here puts it. cargo needs neither: the runner compiles with <code>cargo test --no-run</code> during the preparation.</p><h2 id="what-to-notice" tabindex="-1">What to notice <a class="header-anchor" href="#what-to-notice" aria-label="Permalink to &quot;What to notice&quot;">​</a></h2><ul><li><strong>A file is one run of its tool.</strong> pytest gets the file and the <code>::name</code> as a node id, the Catch2 binary gets it as a test spec, and errand reads their reports back: counts, failed names.</li><li><strong>Filters are the tools&#39; own.</strong> <code>-m &quot;not slow&quot;</code> for pytest, <code>::~[slow]</code> for Catch2.</li><li><strong>A missing pytest is installed when the environment is errand&#39;s.</strong> Into a venv, a micromamba environment or a container, errand installs it and says so. Into the system interpreter it declines and tells you what to run.</li><li><strong>Nothing was converted.</strong> <code>pytest tests/</code> and <code>./cpp/test_geometry</code> still work as before.</li></ul><p>Each runner has its page: <a href="./pytest">Pytest</a>, <a href="./catch2">Catch2</a>, <a href="./cargo">Cargo</a>.</p>`,27)])])}const g=i(n,[["render",h]]);export{c as __pageData,g as default};
